class BracketAnalyzer:
    @staticmethod
    def has_nested_bracket(s: str) -> bool:
        n = len(s)
        for i in range(n):
            if s[i] == ']':
                continue
            cnt = 0
            max_depth = 0
            for j in range(i, n):
                c = s[j]
                if c == '[':
                    cnt += 1
                    if cnt > max_depth:
                        max_depth = cnt
                elif c == ']':
                    cnt -= 1

                if cnt == 0:
                    if max_depth >= 2:
                        return True
                    else:
                        break
        return False


