import sys
data = sys.stdin.read().strip().split()
# Convert to floats if possible, else integers
nums = []
for x in data:
    try:
        if '.' in x or 'e' in x.lower():
            nums.append(float(x))
        else:
            nums.append(int(x))
    except ValueError:
        pass  # ignore non-numeric inputs

if not nums:
    print("No numbers provided")
    sys.exit(0)

# Compute negative maximum (largest value among negatives) and positive minimum (smallest value among positives)
negatives = [n for n in nums if n < 0]
positives = [n for n in nums if n > 0]

neg_max = max(negatives) if negatives else None
pos_min = min(positives) if positives else None

# Output results; print as numbers or indicate when not present
if neg_max is None:
    print("No negative numbers")
else:
    print(neg_max)

if pos_min is None:
    print("No positive numbers")
else:
    print(pos_min)

